import { expect, test, type APIRequestContext } from '@playwright/test';

const adminPassword = 'e2e-admin-password';

interface Activity {
  id: string;
  parentId: string | null;
  level: number;
  time: string;
  title: string;
  status: string;
}

interface DashboardData {
  activities: Activity[];
  dashboardTitle: string;
  lastUpdated: string;
}

async function loginAsAdmin(request: APIRequestContext) {
  const response = await request.post('/api/auth/login', { data: { pw: adminPassword, role: 'admin' } });
  expect(response.ok()).toBeTruthy();
}

async function readData(request: APIRequestContext): Promise<DashboardData> {
  return (await request.get('/api/activities')).json();
}

const tree: Activity[] = [
  { id: 'root', parentId: null, level: 1, time: '23:30 ~ 00:40', title: '[E2E] 없는 대상 검증 작업', status: '대기' },
  { id: 'child', parentId: 'root', level: 2, time: '23:30 ~ 00:00', title: '[E2E] 없는 대상 검증 하위', status: '대기' },
];

const missingId = 'e2e-없는-작업-id';

let original: DashboardData;

test.beforeEach(async ({ request }) => {
  original = await readData(request);
  await loginAsAdmin(request);
  const imported = await request.put('/api/activities', { data: { activities: tree } });
  expect(imported.status(), await imported.text()).toBe(200);
});

test.afterEach(async ({ request }) => {
  await loginAsAdmin(request);
  await request.put('/api/activities', {
    data: { activities: original.activities, dashboardTitle: original.dashboardTitle },
  });
});

/**
 * 분기는 성립했지만 targetId 가 데이터에 없는 PUT 은 404 여야 하고, 저장된 활동·lastUpdated 를
 * 건드리지 않아야 한다. 200 이면 다른 관리자가 이미 지운 행을 건드린 관리자에게 오류 배너 없이
 * "저장됐다" 로 보이고, 전진한 lastUpdated 가 남의 expectedLastUpdated 를 쓸데없이 409 로 만든다.
 */
async function expectNotFoundAndUnchanged(request: APIRequestContext, body: unknown) {
  const before = await readData(request);

  const response = await request.put('/api/activities', { data: body });
  expect(response.status(), await response.text()).toBe(404);
  const result = await response.json() as { error?: string; code?: string };
  expect(typeof result.error).toBe('string');
  expect(result.error).not.toBe('');
  expect(result.code).toBe('TARGET_NOT_FOUND');

  const after = await readData(request);
  expect(after.activities).toEqual(before.activities);
  expect(after.lastUpdated).toBe(before.lastUpdated);
}

test('없는 targetId 의 delete PUT 은 404 이고 저장 내용이 그대로다', async ({ request }) => {
  await expectNotFoundAndUnchanged(request, { action: 'delete', targetId: missingId });
});

test('없는 targetId 의 move PUT 은 404 이고 저장 내용이 그대로다', async ({ request }) => {
  await expectNotFoundAndUnchanged(request, { action: 'move', targetId: missingId, direction: 'up' });
  await expectNotFoundAndUnchanged(request, { action: 'move', targetId: missingId, direction: 'down' });
});

test('없는 targetId 의 상태변경 PUT 은 404 이고 저장 내용이 그대로다', async ({ request }) => {
  await expectNotFoundAndUnchanged(request, { targetId: missingId, newStatus: '완료' });
});

test('없는 parentId 의 add PUT 은 404 이고 저장 내용이 그대로다', async ({ request }) => {
  // 다른 관리자가 이미 지운 행의 ➕(하위 추가). 404 가 아니면 부모 없는 활동이 만들어져
  // 업로드 검증기가 400 'activity.json 데이터 형식이 올바르지 않습니다.' 를 돌려주고,
  // 관리 화면 배너에는 실제 원인(그 행이 사라졌다)과 할 일이 전혀 보이지 않는다.
  await expectNotFoundAndUnchanged(request, { action: 'add', parentId: missingId });
});

test('기존 add 200 계약은 그대로다 — 최상위 추가와 존재하는 부모 아래 추가', async ({ request }) => {
  const before = await readData(request);

  const topLevel = await request.put('/api/activities', { data: { action: 'add', parentId: null } });
  expect(topLevel.status(), await topLevel.text()).toBe(200);
  expect((await readData(request)).activities).toHaveLength(before.activities.length + 1);

  const child = await request.put('/api/activities', { data: { action: 'add', parentId: 'root' } });
  expect(child.status(), await child.text()).toBe(200);
  expect((await readData(request)).activities).toHaveLength(before.activities.length + 2);
});

test('분기 자체가 성립하지 않는 요청은 404 가 아니라 400 UNSUPPORTED_ACTION 이다', async ({ request }) => {
  // direction 이 up/down 이 아니면 move 분기에 들어가지 않는다 — 대상 존재 여부를 보기 전에 400 이다.
  const badDirection = await request.put('/api/activities', {
    data: { action: 'move', targetId: missingId, direction: 'left' },
  });
  expect(badDirection.status(), await badDirection.text()).toBe(400);
  expect((await badDirection.json() as { code?: string }).code).toBe('UNSUPPORTED_ACTION');

  const unknownAction = await request.put('/api/activities', {
    data: { action: 'rename', targetId: missingId },
  });
  expect(unknownAction.status(), await unknownAction.text()).toBe(400);
  expect((await unknownAction.json() as { code?: string }).code).toBe('UNSUPPORTED_ACTION');
});

test('기존 200 계약은 그대로다 — dashboardTitle 단독과 targetId 를 함께 보내는 배열 PUT', async ({ request }) => {
  const titleOnly = await request.put('/api/activities', { data: { dashboardTitle: '[E2E] 없는 대상 제목' } });
