import { expect, test, type APIRequestContext } from '@playwright/test';

const adminPassword = 'e2e-admin-password';

interface Activity {
  id: string;
  parentId: string | null;
  level: number;
  time: string;
  title: string;
  status: string;
}

async function loginAsAdmin(request: APIRequestContext) {
  const response = await request.post('/api/auth/login', { data: { pw: adminPassword, role: 'admin' } });
  expect(response.ok()).toBeTruthy();
}

async function activities(request: APIRequestContext): Promise<Activity[]> {
  return (await (await request.get('/api/activities')).json()).activities;
}

/** 업로드한 activity.json 처럼 id 가 `부모-번호` 꼴이 아닌 트리. `net-x` 는 접두사만 같고 다른 부모 아래에 있다. */
const arbitraryTree: Activity[] = [
  { id: 'net', parentId: null, level: 1, time: '23:30 ~ 00:40', title: '[E2E] 네트워크 작업', status: '대기' },
  { id: 'vlan', parentId: 'net', level: 2, time: '23:30 ~ 00:00', title: '[E2E] VLAN 통합', status: '대기' },
  { id: 'vlan-check', parentId: 'vlan', level: 3, time: '00:00 ~ 00:10', title: '[E2E] VLAN 점검', status: '대기' },
  { id: 'db', parentId: null, level: 1, time: '00:40 ~ 01:10', title: '[E2E] DB 작업', status: '대기' },
  { id: 'net-x', parentId: 'db', level: 2, time: '00:40 ~ 01:00', title: '[E2E] DB 전환', status: '대기' },
];

let original: Activity[];

test.beforeEach(async ({ request }) => {
  original = await activities(request);
  await loginAsAdmin(request);
  const imported = await request.put('/api/activities', { data: { activities: arbitraryTree } });
  expect(imported.status(), await imported.text()).toBe(200);
});

test.afterEach(async ({ request }) => {
  await loginAsAdmin(request);
  await request.put('/api/activities', { data: { activities: original } });
});

test('120자 ID 부모 아래 추가한 자식이 저장되고 기존 항목은 유지된다', async ({ request }) => {
  const parent = { ...arbitraryTree[0], id: 'p'.repeat(120) };
  const seed = [parent, arbitraryTree[3], arbitraryTree[4]];
  const imported = await request.put('/api/activities', { data: { activities: seed } });
  expect(imported.status(), await imported.text()).toBe(200);
  expect(await activities(request)).toEqual(seed);

  const added = await request.put('/api/activities', { data: { action: 'add', parentId: parent.id } });
  expect(added.status(), await added.text()).toBe(200);
  const saved = (await added.json()).activities as Activity[];
  expect(saved).toHaveLength(seed.length + 1);
  expect(saved.slice(0, -1)).toEqual(seed);
  const child = saved[saved.length - 1];
  expect(typeof child.id).toBe('string');
  expect(child.id.length).toBeGreaterThan(0);
  expect(child.id.length).toBeLessThanOrEqual(120);
  expect(seed.map((activity) => activity.id)).not.toContain(child.id);
  expect(child).toEqual({
    id: child.id, parentId: parent.id, level: parent.level + 1,
    time: '미정', title: '새 액티비티', status: '대기',
  });

  // 성공 응답뿐 아니라 저장 후 GET에서도 같은 자식과 부모 관계가 유지되어야 한다.
  expect(await activities(request)).toEqual(saved);
});

test('임의 id 트리에서 부모를 지우면 parentId 로 이어진 하위까지 함께 사라진다', async ({ request }) => {
  const deleted = await request.put('/api/activities', { data: { action: 'delete', targetId: 'net' } });
  expect(deleted.status(), await deleted.text()).toBe(200);

  const remaining = (await activities(request)).map((activity) => activity.id);
  expect(remaining).not.toContain('net');
  expect(remaining).not.toContain('vlan');
  expect(remaining).not.toContain('vlan-check');
  // 접두사만 같고 parentId 는 다른 항목은 남는다
  expect(remaining).toEqual(['db', 'net-x']);
});

