  /**
   * 활동 변경 PUT 한 곳. 응답을 반드시 읽어 실패면 화면에 남긴다.
   * SWR 1초 폴링이 실패한 값을 조용히 되돌리므로, 성공 여부는 이 응답으로만 판단한다.
   */
  const submitActivityChange = async (body: Record<string, unknown>): Promise<boolean> => {
    try {
      const res = await fetch('/api/activities', {
        method: 'PUT',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(body),
      });

      if (!res.ok) {
        const result = await res.json().catch(() => null) as { error?: string } | null;
        if (res.status === 401) {
          handleUnauthorized();
          return false;
        }
        setSaveError(result?.error ?? `변경 사항을 저장하지 못했습니다. (HTTP ${res.status})`);
        return false;
      }

      setSaveError('');
      // 성공한 PUT 은 새 lastUpdated 를 포함한 완전한 ActivitiesData 를 돌려준다. 그것을 그대로
      // 캐시에 넣어야 내 쓰기만큼 스냅샷이 전진한다 — GET 이 실패하는 동안 재요청만 하면 스냅샷이
      // 첫 로드에 멈춰, 혼자 일하는데도 두 번째 저장부터 전부 409(STALE_SNAPSHOT)로 막힌다.
      const result = await res.json().catch(() => null) as ActivitiesData | null;
      if (result) void mutate(result, { revalidate: false });
      else void mutate();
      return true;
    } catch (error) {
      setSaveError(
        `서버에 연결하지 못해 변경 사항을 저장하지 못했습니다. (${error instanceof Error ? error.message : '알 수 없는 네트워크 오류'})`,
      );
      return false;
    }
  };

  const saveDashboardTitle = async () => {
    // 저장이 성공했을 때만 편집을 닫는다. 실패하면 입력한 제목이 그대로 남는다.
    if (await submitActivityChange({ dashboardTitle: editTitle })) setIsEditingTitle(false);
  };

  if (!authChecked) {
    return (
      <div className="min-h-screen bg-[#0A2A66] flex items-center justify-center text-white">
          {tree.map(node => (
            <ActivityTree 
              key={node.id} 
              node={node} 
              forceCollapsed={false}
              isAdmin={true}
              onStatusChange={async (id, newStatus) => {
                let activities = [...(data?.activities ?? [])];

                // 대상과 모든 하위(parentId 관계)를 같은 상태로
                const affected = collectDescendantIds(activities, id);
                activities = activities.map((a: Activity) => {
                  if (affected.has(a.id)) {
                    return { ...a, status: newStatus };
                  }
                  return a;
                });

                // 부모 자동 진행 처리
                if (newStatus === '대기' || newStatus === '진행') {
                  const target = activities.find((a: Activity) => a.id === id);
                  if (target?.parentId) {
                    activities = activities.map((a: Activity) => {
                      if (a.id === target.parentId) {
                        return { ...a, status: '진행' };
                      }
                      return a;
                    });
                  }
                }

                // 자식 모두 완료 시 부모 완료
                if (newStatus === '완료') {
                  const target = activities.find((a: Activity) => a.id === id);
                  if (target?.parentId) {
                    const siblings = activities.filter((a: Activity) => a.parentId === target.parentId);
                    if (siblings.every((a: Activity) => a.status === '완료')) {
                      activities = activities.map((a: Activity) => {
                        if (a.id === target.parentId) {
                          return { ...a, status: '완료' };
                        }
                        return a;
                      });
                    }
                  }
                }

                // 스냅샷 시점을 함께 보낸다. 그 사이 다른 관리자가 바꿨으면 서버가 409 로 막는다.
                await submitActivityChange({
                  activities,
                  targetId: id,
                  newStatus,
                  ...(data ? { expectedLastUpdated: data.lastUpdated } : {}),
                });
              }}
              onUpdateActivity={async (id, updated) => {
                const newActivities = (data?.activities ?? []).map((a: Activity) =>
                  a.id === id ? { ...a, ...updated } : a
                );
                return submitActivityChange({
                  activities: newActivities,
                  targetId: id,
                  ...(data ? { expectedLastUpdated: data.lastUpdated } : {}),
                });
              }}
              onDeleteActivity={async (id) => {
                // 확인창은 ActivityTree 의 삭제 버튼에서 한 번만 띄운다(그쪽이 지우는 노드를 안다).
                await submitActivityChange({ action: 'delete', targetId: id });
              }}
              onMoveActivity={async (id, direction) => {
                await submitActivityChange({ action: 'move', targetId: id, direction });
              }}
              onAddActivity={async (parentId) => {
                await submitActivityChange({ action: 'add', parentId });
              }}
            />
          ))}

          {/* 트리가 비면 행 안의 추가 버튼도 함께 사라지므로, 최상위 추가는 목록 밖에 항상 둔다. */}
          <button
            data-testid="add-root-activity"
            onClick={() => { void submitActivityChange({ action: 'add', parentId: null }); }}
            className="flex w-full items-center justify-center gap-2 rounded-2xl border border-dashed border-gray-300 px-4 py-3 text-sm font-medium text-blue-600 transition hover:border-blue-400 hover:bg-blue-50"
          >
            <Plus size={18} />
