'use client';

import { ChangeEvent, DragEvent, useRef, useState } from 'react';
import { AlertCircle, CheckCircle2, Download, FileJson, Loader2, Upload } from 'lucide-react';
import type { ActivitiesData } from '@/lib/types';

const MAX_FILE_SIZE = 2 * 1024 * 1024;

interface ValidationIssue {
  path: string;
  message: string;
}

interface ImportFeedback {
  kind: 'success' | 'error';
  title: string;
  details?: ValidationIssue[];
}

interface ImportResponse {
  success?: boolean;
  error?: string;
  details?: ValidationIssue[];
  importedCount?: number;
  normalizedLegacyStatuses?: number;
  data?: ActivitiesData;
}

interface Props {
  currentData?: ActivitiesData;
  onImported: (data: ActivitiesData) => void;
  onUnauthorized: () => void;
}

function formatFileSize(size: number) {
  if (size < 1024) return `${size} B`;
  return `${(size / 1024).toFixed(1)} KB`;
}

export default function ActivityJsonImporter({ currentData, onImported, onUnauthorized }: Props) {
  const inputRef = useRef<HTMLInputElement>(null);
  const [selectedFile, setSelectedFile] = useState<File | null>(null);
  const [previewCount, setPreviewCount] = useState<number | null>(null);
  const [isDragging, setIsDragging] = useState(false);
  const [isUploading, setIsUploading] = useState(false);
  const [feedback, setFeedback] = useState<ImportFeedback | null>(null);
  const canUpload = Boolean(
    selectedFile
    && selectedFile.size > 0
    && selectedFile.size <= MAX_FILE_SIZE
    && selectedFile.name.toLowerCase().endsWith('.json'),
  );

  const inspectFile = async (file: File) => {
    setSelectedFile(file);
    setPreviewCount(null);
    setFeedback(null);

    if (!file.name.toLowerCase().endsWith('.json')) {
      setFeedback({
        kind: 'error',
        title: 'JSON 파일만 선택할 수 있습니다.',
        details: [{ path: 'file', message: `선택한 파일명: ${file.name}` }],
      });
      return;
    }

    if (file.size === 0 || file.size > MAX_FILE_SIZE) {
      setFeedback({
        kind: 'error',
        title: file.size === 0 ? '선택한 파일이 비어 있습니다.' : '파일 크기는 2MB 이하여야 합니다.',
        details: [{ path: 'file', message: `현재 파일 크기: ${formatFileSize(file.size)}` }],
      });
      return;
    }

    try {
      const parsed: unknown = JSON.parse((await file.text()).replace(/^\uFEFF/, ''));
      if (
        typeof parsed === 'object'
        && parsed !== null
        && !Array.isArray(parsed)
        && Array.isArray((parsed as Record<string, unknown>).activities)
      ) {
        setPreviewCount(((parsed as Record<string, unknown>).activities as unknown[]).length);
      }
    } catch {
      // 서버가 행/열 정보를 포함한 상세 JSON 문법 오류를 반환하도록 업로드는 허용합니다.
    }
  };

  const handleFileChange = (event: ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0];
    if (file) void inspectFile(file);
  };

  const handleDrop = (event: DragEvent<HTMLDivElement>) => {
    event.preventDefault();
    setIsDragging(false);
    const file = event.dataTransfer.files?.[0];
    if (file) void inspectFile(file);
  };

  const handleUpload = async () => {
    if (!selectedFile) {
      setFeedback({ kind: 'error', title: '업로드할 activity.json 파일을 선택해 주세요.' });
      return;
    }
    if (selectedFile.size === 0 || selectedFile.size > MAX_FILE_SIZE || !selectedFile.name.toLowerCase().endsWith('.json')) {
      return;
    }

    const countLabel = previewCount === null ? '파일의 데이터' : `${previewCount.toLocaleString('ko-KR')}개 액티비티`;
    if (!window.confirm(`${countLabel}로 현재 상황판을 교체하시겠습니까?\n교체 직전 데이터는 서버에 백업됩니다.`)) {
      return;
    }

    setIsUploading(true);
    setFeedback(null);

    try {
      const formData = new FormData();
      formData.append('file', selectedFile);
      const response = await fetch('/api/activities/import', { method: 'POST', body: formData });
      const result = await response.json().catch(() => ({
        error: `서버 응답을 해석하지 못했습니다. (HTTP ${response.status})`,
      })) as ImportResponse;

      if (!response.ok || !result.data) {
        setFeedback({
          kind: 'error',
          title: result.error ?? `업로드에 실패했습니다. (HTTP ${response.status})`,
          details: result.details,
        });
        if (response.status === 401) onUnauthorized();
        return;
      }

      onImported(result.data);
      const normalizedMessage = result.normalizedLegacyStatuses
        ? ` · 기존 상태값 '진행중' ${result.normalizedLegacyStatuses}건을 '진행'으로 변환했습니다.`
        : '';
      setFeedback({
        kind: 'success',
        title: `${(result.importedCount ?? result.data.activities.length).toLocaleString('ko-KR')}개 액티비티를 반영했습니다.${normalizedMessage}`,
      });
      setSelectedFile(null);
      setPreviewCount(null);
      if (inputRef.current) inputRef.current.value = '';
    } catch (error) {
      setFeedback({
        kind: 'error',
        title: '서버에 연결하지 못해 업로드에 실패했습니다.',
        details: [{ path: 'network', message: error instanceof Error ? error.message : '알 수 없는 네트워크 오류' }],
      });
import { expect, test, type APIRequestContext, type Page } from '@playwright/test';

const adminPassword = 'e2e-admin-password';

interface Activity {
  id: string;
