async function loginAsAdmin(request: APIRequestContext) {
  const response = await request.post('/api/auth/login', { data: { pw: adminPassword, role: 'admin' } });
  expect(response.ok()).toBeTruthy();
}

async function readData(request: APIRequestContext): Promise<{ activities: Activity[]; dashboardTitle: string }> {
  return (await request.get('/api/activities')).json();
}

/** 최상위와 하위의 제목이 서로 달라야 확인창이 어느 항목을 가리키는지 구분된다. */
const tree: Activity[] = [
  { id: 'root', parentId: null, level: 1, time: '23:30 ~ 00:40', title: '[E2E] 최상위 작업', status: '대기' },
  { id: 'child', parentId: 'root', level: 2, time: '23:30 ~ 00:00', title: '[E2E] 하위 작업', status: '대기' },
];

let original: { activities: Activity[]; dashboardTitle: string };

test.beforeEach(async ({ request }) => {
  original = await readData(request);
  await loginAsAdmin(request);
  const imported = await request.put('/api/activities', { data: { activities: tree } });
  expect(imported.status(), await imported.text()).toBe(200);
});

test.afterEach(async ({ request }) => {
  await loginAsAdmin(request);
  await request.put('/api/activities', {
    data: { activities: original.activities, dashboardTitle: original.dashboardTitle },
  });
});

async function loginThroughUi(page: Page) {
  await page.goto('/admin');
  await page.getByPlaceholder('관리자 비밀번호').fill(adminPassword);
  await page.getByRole('button', { name: '로그인' }).click();
  await expect(page.getByText('[E2E] 하위 작업', { exact: true })).toBeVisible();
}

/** 트리 행의 상태 드롭다운만. 설정 카드의 select 는 '완료' 옵션이 없다. */
function statusSelects(page: Page) {
  return page.locator('select').filter({ has: page.locator('option[value="완료"]') });
}

/** PUT 만 500 으로 돌려준다. GET(SWR 폴링)은 그대로 통과시킨다. */
async function failEveryPut(page: Page) {
  await page.route('**/api/activities', async (route) => {
    if (route.request().method() !== 'PUT') return route.fallback();
    await route.fulfill({
      status: 500,
      contentType: 'application/json',
      body: JSON.stringify({ error: '상황판 데이터를 저장하지 못했습니다.' }),
    });
  });
}

function waitForPut(page: Page) {
  return page.waitForResponse((r) => r.url().includes('/api/activities') && r.request().method() === 'PUT');
}

test('활동 상태 변경 PUT 이 실패하면 관리 화면에 실패 메시지가 보이고, 성공하면 사라진다', async ({ page }) => {
  await loginThroughUi(page);
  await expect(statusSelects(page)).toHaveCount(2);

  await failEveryPut(page);
  await statusSelects(page).nth(1).selectOption('완료');
  await expect(page.getByTestId('admin-save-error')).toContainText('상황판 데이터를 저장하지 못했습니다.');

  // 가로채기를 풀면 같은 조작이 성공하고 메시지가 사라진다.
  await page.unroute('**/api/activities');
  const putDone = waitForPut(page);
  await statusSelects(page).nth(1).selectOption('지연');
  expect((await putDone).status()).toBe(200);
  await expect(page.getByTestId('admin-save-error')).toHaveCount(0);

  const byId = new Map((await readData(page.request)).activities.map((a) => [a.id, a.status]));
  expect(byId.get('child')).toBe('지연');
});

test('활동 변경이 401 이면 다시 로그인 화면으로 돌아간다', async ({ page }) => {
